BEGIN;
ALTER TABLE mcp_connections ADD COLUMN IF NOT EXISTS paused_at timestamptz;
ALTER TABLE mcp_connections ADD COLUMN IF NOT EXISTS budget_pico numeric(36,0) CHECK(budget_pico>=0);
ALTER TABLE mcp_connections ADD COLUMN IF NOT EXISTS max_request_pico numeric(36,0) CHECK(max_request_pico>=0);
ALTER TABLE mcp_connections ADD COLUMN IF NOT EXISTS token_expires_at timestamptz;
CREATE INDEX IF NOT EXISTS mcp_draft_connection ON mcp_drafts(office_id,connection_id,created_at DESC);
INSERT INTO chancery_schema(version) VALUES(12) ON CONFLICT DO NOTHING;
COMMIT;
BEGIN;
CREATE TABLE IF NOT EXISTS agent_oauth_clients(id text PRIMARY KEY,name text NOT NULL,redirect_uris jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE mcp_connections ADD COLUMN IF NOT EXISTS oauth_client_id text REFERENCES agent_oauth_clients(id);
CREATE TABLE IF NOT EXISTS agent_oauth_pending(id text PRIMARY KEY,client_id text NOT NULL REFERENCES agent_oauth_clients(id),parameters jsonb NOT NULL,expires_at timestamptz NOT NULL,used_at timestamptz);
CREATE TABLE IF NOT EXISTS agent_oauth_codes(code_hash text PRIMARY KEY,client_id text NOT NULL REFERENCES agent_oauth_clients(id),connection_id text NOT NULL REFERENCES mcp_connections(id),office_id text NOT NULL REFERENCES offices(id),redirect_uri text NOT NULL,challenge text NOT NULL,token_enc text,expires_at timestamptz NOT NULL,used_at timestamptz);
CREATE TABLE IF NOT EXISTS agent_oauth_refresh(token_hash text PRIMARY KEY,client_id text NOT NULL REFERENCES agent_oauth_clients(id),connection_id text NOT NULL REFERENCES mcp_connections(id),expires_at timestamptz NOT NULL,used_at timestamptz);
GRANT SELECT,INSERT,UPDATE,DELETE ON agent_oauth_clients,agent_oauth_pending,agent_oauth_codes,agent_oauth_refresh TO chancery_service;
GRANT UPDATE(token_hash,token_expires_at,revoked_at) ON mcp_connections TO chancery_service;
DROP POLICY IF EXISTS service_oauth_rotation ON mcp_connections;
CREATE POLICY service_oauth_rotation ON mcp_connections FOR UPDATE TO chancery_service USING(oauth_client_id IS NOT NULL) WITH CHECK(oauth_client_id IS NOT NULL);
COMMIT;
